insert into public.plan_days (day_number, phase, dsa_description, design_description, behavioral_description) values
(1,'P1','Arrays/Hashing patterns: Two Sum, Group Anagrams, Top K Frequent. Time-box each at 25 min.','LLD basics: SOLID principles deep-dive. Write notes with code examples for each.','Inventory: list 8-10 significant projects from your 12 YoE. Tag each with possible STAR themes.'),
(2,'P1','Two Pointers: Valid Palindrome, 3Sum, Container With Most Water, Trapping Rain Water.','LLD: Design a Parking Lot. Write out classes, relationships, write code in your strongest language.','Pick top 5 stories. Draft Situation+Task for each in 3-4 lines.'),
(3,'P1','Sliding Window: Best Time Buy/Sell Stock, Longest Substring Without Repeat, Min Window Substring.','LLD: Design Snake & Ladder / Tic Tac Toe. Focus on extensibility.','Draft Action+Result for the 5 stories. Quantify impact wherever possible.'),
(4,'P1','Stack: Valid Parens, Min Stack, Daily Temperatures, Largest Rectangle in Histogram.','Design Patterns: Strategy, Observer, Factory. Code real examples, not toy ones.','Amazon LP mapping: map each story to 1-3 Leadership Principles.'),
(5,'P1','Binary Search variants: Search Rotated Sorted Array, Find Min in Rotated, Median of Two Sorted Arrays.','Design Patterns: Singleton (with thread safety), Builder, Decorator. Code examples.','Practice tell-me-about-yourself: 90 sec version + 3 min version.'),
(6,'P1','Linked List: Reverse, Merge K Sorted Lists, LRU Cache (must memorize), Reorder List.','LLD: Design an LRU Cache with thread safety. Implement in code (Doubly LL + HashMap).','Mock yourself recording: ''Tell me about a time you disagreed with a leader''.'),
(7,'P1','Weekend long session. Trees Part 1: Invert, Max Depth, Same Tree, Diameter, Balanced.','HLD primer: read about latency numbers, throughput vs latency, CAP theorem, ACID vs BASE.','Write down your ''reason for switching'' answer. Polish for 12 YoE narrative.'),
(8,'P1','Trees Part 2: BFS/DFS, Level Order, Right Side View, LCA, Validate BST.','HLD primer: load balancing, reverse proxies, CDN, caching strategies (cache-aside, write-through, write-back).','Story: ''Most challenging technical problem''. Draft full STAR.'),
(9,'P1','Trees Part 3: Serialize/Deserialize Binary Tree, Path Sum III, Kth Smallest in BST, Construct from Preorder+Inorder.','HLD: Designing primitives - SQL vs NoSQL, when to use each. Read about indexes, B-trees, LSM-trees.','Story: ''Time you took a big risk''. Draft STAR.'),
(10,'P1','Heap/Priority Queue: Top K Frequent, K Closest Points, Find Median from Data Stream, Task Scheduler.','LLD: Design Library Management System. Focus on entity modeling and API design.','Story: ''Time you mentored or grew an engineer''. Important for senior level.'),
(11,'P1','Backtracking: Subsets, Permutations, Combination Sum, Word Search, N-Queens.','HLD: Sharding, replication (master-slave, master-master), consistent hashing - learn deeply.','Story: ''Failure and what you learned''. Draft. Avoid trivial failures.'),
(12,'P1','Graphs Part 1: Number of Islands, Clone Graph, Course Schedule (cycle detection), Pacific Atlantic.','HLD: Message queues - Kafka vs RabbitMQ vs SQS. When and why. Pub-sub vs queue.','Story: ''Conflict with peer or manager''. Draft. Tone matters.'),
(13,'P1','Graphs Part 2: Topological Sort, Word Ladder, Alien Dictionary, Min Cost Connect Points (MST).','LLD: Design ATM / Vending Machine - state machine pattern.','Behavioral mock: pick 3 prompts from Amazon LP list, answer aloud.'),
(14,'P1','DP Part 1 (1D): Climbing Stairs, House Robber I/II, Coin Change, Word Break, Longest Increasing Subseq.','HLD: Rate limiter design. Token bucket, leaky bucket, sliding window. Code the algorithm too.','Behavioral mock: Googleyness/leadership prompts.'),
(15,'P1','Phase 1 review: Re-solve 5 random problems from Days 1-14 cold. Identify patterns you missed.','Review LLD code from Days 2,6,10,13. Refactor at least one for cleaner abstraction.','Write a ''Phase 1 retrospective'' - what''s still weak? Adjust Phase 2 priorities accordingly.'),
(16,'P2','DP Part 2 (2D): Longest Common Subseq, Edit Distance, Unique Paths, 0/1 Knapsack.','HLD Case Study 1: Design URL Shortener (TinyURL). Full whiteboard - reqs, capacity, API, schema, scaling.','Refine top 3 stories with quantified impact. Replace ''I did X'' with ''I led X resulting in Y''.'),
(17,'P2','DP Part 3 (Hard): Longest Palindromic Subseq, Distinct Subseq, Burst Balloons, Regex Matching.','HLD Case Study 1 continued: trade-offs - Base62 vs hashing, DB choice, cache design, analytics layer.','Story drill: 2 prompts cold, 5 min each, no notes.'),
(18,'P2','Intervals: Merge Intervals, Insert, Non-overlapping, Meeting Rooms I/II.','HLD Case Study 2: Design Pastebin / Dropbox file storage. Focus on storage, metadata, chunking.','Manager round prep: ''How do you give critical feedback?'' Draft answer.'),
(19,'P2','Greedy: Jump Game, Gas Station, Hand of Straights, Merge Triplets.','HLD Case Study 3: Design Twitter / News Feed. Fan-out write vs fan-out read trade-offs.','Manager round: ''How do you handle underperformer?'' Draft.'),
(20,'P2','Bit Manipulation + Math: Single Number, Counting Bits, Reverse Bits, Missing Number, Pow(x,n).','HLD Case Study 3 continued: timeline storage, celebrity problem, push vs pull, redis sorted sets.','Manager round: ''How do you prioritize work for your team?'' Draft.'),
(21,'P2','Weekend: solve 1 hard problem from each of - DP, Graphs, Trees. 45 min each, then study optimal solutions.','HLD Case Study 4: Design WhatsApp / Chat. Long polling vs WebSocket vs SSE. Online presence.','Behavioral mock with friend or AI: 30 min, 3 stories.'),
(22,'P2','Tagged company practice: 10 LeetCode problems tagged Google or Meta (whichever you target most).','HLD Case Study 4 continued: group chat, message ordering, end-to-end encryption basics.','Refine story for ''biggest impact you''ve had''. This is THE story for senior level.'),
(23,'P2','Tagged: 10 LC problems tagged Amazon. Notice Amazon style: more graph/heap/string-heavy.','HLD Case Study 5: Design Uber / Ride-sharing. Geohashing, quad-trees, matching algorithm.','Story for ''how you influence without authority'' - critical at staff level.'),
(24,'P2','Tries: Implement Trie, Design Add+Search Words, Word Search II.','HLD Case Study 5 continued: real-time location updates, surge pricing, ETA computation.','Practice ''what''s your biggest weakness'' - have a real one with concrete improvement.'),
(25,'P2','Advanced graphs: Network Delay Time (Dijkstra), Cheapest Flights K Stops, Swim in Rising Water.','LLD Deep Dive: Design Splitwise / Expense sharing. Focus on debt simplification algorithm.','Bar Raiser style mock if Amazon target: 4 LP-mapped stories rapid fire.'),
(26,'P2','Strings: KMP basics, Rabin-Karp, Longest Palindromic Substring, Z-algorithm overview.','HLD Case Study 6: Design YouTube / Netflix. Video upload pipeline, encoding, CDN, recommendations.','Tech lead questions: ''How do you make a tech decision when team disagrees?'''),
(27,'P2','Union-Find: Number of Connected Components, Redundant Connection, Accounts Merge.','HLD Case Study 6 continued: storage at scale, DASH/HLS streaming, view count consistency.','Tech lead: ''How do you handle technical debt vs feature delivery?'''),
(28,'P2','Weekend: Mock interview #1 (DSA, 60 min, 2 problems on LeetCode in interview mode or paid platform).','HLD Case Study 7: Design Search Autocomplete + Search Ranking basics.','Self-review yesterday''s behavioral answers. Are you concise? Cut filler.'),
(29,'P2','Review mock #1 weaknesses. Re-solve missed problems. Study optimal patterns.','HLD: Idempotency, distributed transactions, saga pattern, two-phase commit.','Story: ''Time you owned a critical incident / outage''. Strong senior signal.'),
(30,'P2','Two-pointer & Sliding Window hard set: Subarrays with K Different Integers, Min Window Substring revisit.','HLD: Designing for observability - logs, metrics, traces. SLO/SLI/SLA - know definitions cold.','Refine ''why this company'' for top 2 target companies. Specific, not generic.'),
(31,'P2','Graph hard set: Word Ladder II, Bus Routes, Reconstruct Itinerary.','HLD Case Study 8: Design Notification System. Multi-channel, dedup, rate limiting per user.','Story for ''time you simplified something complex'' - architecture or process.'),
(32,'P2','DP hard set: Best Time to Buy/Sell Stock with Cooldown, IV (k transactions), Dungeon Game.','HLD Case Study 9: Design Distributed Cache (like Redis). Eviction, replication, hot-key problem.','Story: ''Cross-team collaboration / dependency you led''.'),
(33,'P2','Heap + Greedy combo: IPO, Reorganize String, Furthest Building You Can Reach.','HLD: API design - REST vs gRPC vs GraphQL. Versioning. Pagination strategies.','Story drill: 4 prompts, 4 min each, time yourself strictly.'),
(34,'P2','Matrix problems: Spiral, Rotate Image, Set Matrix Zeros, Word Search.','HLD Case Study 10: Design Google Drive / collaborative editing primer (OT vs CRDT awareness).','Final pass on Amazon LP coverage if targeting Amazon - need 14-16 stories minimum.'),
(35,'P2','Phase 2 retrospective: pick the 2 weakest topics. Plan extra hours for them in Phase 3.','HLD Case Study 11: Design a metrics/monitoring system (like Datadog primer).','Read failure mode stories online (Pragmatic Engineer, Levels.fyi posts) to recalibrate bar.'),
(36,'P3','Mock #2 - DSA, 60 min, recorded. Use Pramp / Interviewing.io / friend.','Mock HLD #1 - 45 min on a system you haven''t designed yet. Record yourself.','Review HLD mock - did you cover: reqs, capacity, API, data model, HLD, deep-dive, trade-offs?'),
(37,'P3','Review mock #2. Re-solve. Study editorial. Note: did you communicate while coding?','HLD Case Study 12: Design Instagram / photo sharing. Feed algorithm, storage tiering.','Polish ''why are you leaving current role'' - never blame, frame forward.'),
(38,'P3','Tagged company: 10 LC problems for company #1 in your target list, focus on 30-day frequency.','HLD Case Study 13: Design Distributed Logging / ELK at scale.','Mock behavioral round - 30 min, 4 stories, get harsh feedback.'),
(39,'P3','Tagged company: 10 LC problems for company #2.','HLD: Multi-region active-active vs active-passive. Disaster recovery (RPO/RTO).','Self-record answer to ''tell me about yourself'' - watch back, fix awkwardness.'),
(40,'P3','Hard problem deep-dive: pick 1 LC hard, spend 90 min understanding 3 different solutions.','LLD Mock: Design Stack Overflow / Q&A site code-level. 60 min, write actual code.','Story: ''Time you said no to a senior leader / pushed back''. Important for staff.'),
(41,'P3','Mock #3 - DSA, 90 min, 2 mediums + 1 hard. Pramp / Interviewing.io.','HLD Case Study 14: Design Slack / Discord. Channels, presence at scale, message search.','Review mock #3. Pattern recognition: are you starting with brute force? You should be.'),
(42,'P3','Weekend full mock loop simulation: 3 x 45 min DSA back-to-back. Stamina test.','HLD Mock #2 - 60 min. Different system from mock #1.','Behavioral mock: 5 prompts, 5 min each. Sustain energy across all 5.'),
(43,'P3','Recovery + review day. Re-solve 5 problems you''ve struggled with most. Spaced repetition.','Review HLD Mock #2. List 5 things you''d say differently next time.','Salary/leveling research: levels.fyi, Blind, Glassdoor for target companies.'),
(44,'P3','Trees + Graphs cold drill: 6 problems, 25 min each. Speed focus.','HLD Case Study 15: Design Online Code Editor (Leetcode/Replit). Sandboxing, real-time exec.','Negotiation prep: read ''Ten Rules for Negotiating'' (haseebq) if not done.'),
(45,'P3','DP + Backtracking cold drill: 5 problems, 30 min each.','HLD Case Study 16: Design Booking System (Airbnb/Hotel). Inventory locking, double-booking.','Refine ''questions for interviewer'' - have 3 sharp ones per round type.'),
(46,'P3','Mock #4 - DSA with focus on weakest topic from previous mocks.','LLD Mock #2: Design Movie Booking System (BookMyShow). Concurrency around seat locking.','Self-recorded behavioral - 30 min, 5 prompts. Watch back.'),
(47,'P3','Review mock #4. Patterns missed? Speed issues? Communication?','HLD: Feature flags, A/B testing infra, gradual rollouts. Important for senior signal.','Practice STAR pruning: take a 6 min answer and cut it to 3 min without losing impact.'),
(48,'P3','Sunday: Simulate real onsite - 4 x 45 min DSA + 1 hour break + behavioral. Endurance test.','Don''t add new HLD content today. Review existing case study notes.','Endurance assessment: how was hour 5? Plan rest before real onsite.'),
(49,'P3','Light DSA day: 3 LC mediums, no time pressure. Read editorials.','HLD Case Study 17: Design Payment System. Idempotency, double-charge prevention, ledger.','Compile your ''final story bank'' - 12-15 polished stories indexed by theme.'),
(50,'P3','Phase 3 retro. Mock scores trending up? Identify final 2-3 gaps to close.','HLD Case Study 18: Design Distributed Job Scheduler / Cron at scale.','Mock behavioral with someone senior if possible. Get honest feedback.'),
(51,'P4','Re-solve LRU Cache, LFU Cache, Median from Data Stream, Trapping Rain Water - the ''must-know'' set.','HLD speed-run: pick 5 case studies from your notes, do 10-min outlines for each.','Read Anthropic/Google/Meta engineering blogs - have a recent thing to discuss.'),
(52,'P4','Tagged company final pass for top target: 8 problems, mix of frequencies.','Final HLD case: Design system specific to your target company''s product.','Final pass on top 5 stories - record once, listen for filler words (''um'',''like'',''sort of'').'),
(53,'P4','Mock #5 - full DSA simulation. 60 min. Recorded. Solo or paid platform.','HLD mock #3 with focus on deep-dive component (not just high level).','Behavioral mock #3 - timed, 30 min, recorded.'),
(54,'P4','Review all mocks together. Common gaps. Do 3 problems on those gaps.','Review HLD weak areas - typically: capacity estimation accuracy, deep-dive specificity.','Compile ''crisis stories'' - performance issues, outages, conflicts - top 3 polished.'),
(55,'P4','Light: 2 LC mediums you''ve solved before, time them, aim for under 20 min each.','HLD: Specific deep-dives on DB internals (B-tree vs LSM, isolation levels) - common follow-ups.','Question bank for interviewer review and freshen up.'),
(56,'P4','Speed drill: 5 easies in 60 min. Should feel automatic at this point.','LLD speed-run: re-implement Parking Lot, LRU, BookMyShow seat locking from memory.','Negotiation script practice. Specific numbers, ranges, walk-away point.'),
(57,'P4','Cool-down: re-solve 3 problems from Day 1 - measure how much faster you are.','Review HLD numbers: latency by component, QPS estimation per layer, storage math.','Polish ''why FAANG / why now'' - your 12 YoE story arc.'),
(58,'P4','Light. 2 problems max. Don''t burn out.','HLD: 2 case studies in 30 min each, just outlines.','Behavioral final mock - go in fresh, treat as real.'),
(59,'P4','REST DAY for technical. Review notes only. Walk, exercise, sleep early.','REST. Skim HLD case study one-liners only.','Mental prep: visualize the interview going well. Logistics check.'),
(60,'P4','Light warm-up: 1 easy problem. Confidence builder. STOP.','Review your HLD framework one-pager only.','Apply / schedule interviews. You''re ready.')
